// Website diagnosis quiz (pages /diagnostico/ and /en/diagnosis/).
// Content comes from the JSON embedded in the page (generated by blog/_quiz.py);
// scoring from assets/quiz-logic.js. The report email goes through
// /api/contact (type "quiz"), with Web3Forms as a fallback.
(function () {
  var stage = document.querySelector(".js-quiz");
  var dataEl = document.getElementById("quiz-data");
  if (!stage || !dataEl || !window.quizEvaluate) return;
  var D = JSON.parse(dataEl.textContent);
  var U = D.ui;
  var EN = /^en/i.test(document.documentElement.lang);
  var QS = D.questions;
  var LAST = QS.length - 1;
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var answers = [];
  var path = []; // indices of the questions shown, for "Back"
  var current = -1;

  var el = function (tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  };

  // Screens cross-fade: the old one fades up and out, the new one fades up in
  var show = function (screen, focusEl) {
    var old = stage.querySelector(".quiz-screen.is-active");
    var put = function () {
      if (old) old.remove();
      stage.appendChild(screen);
      requestAnimationFrame(function () { requestAnimationFrame(function () { screen.classList.add("is-active"); }); });
      if (focusEl) setTimeout(function () { focusEl.focus({ preventScroll: true }); }, 50);
      var top = stage.getBoundingClientRect().top;
      if (top < 0 || top > window.innerHeight * 0.4) {
        var y = window.scrollY + top - 120;
        window.scrollTo({ top: Math.max(0, y), behavior: reduce ? "auto" : "smooth" });
      }
    };
    if (old && !reduce) { old.classList.add("is-leaving"); setTimeout(put, 280); } else { put(); }
  };

  var total = function () { return answers[0] != null && QS[0].options[answers[0]].skip ? 2 : QS.length; };
  var position = function (i) { return answers[0] != null && QS[0].options[answers[0]].skip && i === LAST ? 2 : i + 1; };

  var renderQuestion = function (i) {
    current = i;
    var q = QS[i];
    var s = el("div", "quiz-screen quiz-q");
    var bar = el("div", "quiz-progress");
    var fill = el("span");
    fill.style.width = Math.round(((position(i) - 1) / total()) * 100) + "%";
    bar.appendChild(fill);
    bar.setAttribute("role", "progressbar");
    bar.setAttribute("aria-valuemin", "0");
    bar.setAttribute("aria-valuemax", String(total()));
    bar.setAttribute("aria-valuenow", String(position(i) - 1));
    s.appendChild(bar);
    s.appendChild(el("p", "quiz-count", U.progress.replace("{n}", position(i)).replace("{t}", total())));
    var h = el("h2", "quiz-question", q.q);
    h.tabIndex = -1;
    s.appendChild(h);
    var list = el("div", "quiz-options");
    q.options.forEach(function (o, k) {
      var b = el("button", "quiz-option" + (answers[i] === k ? " is-selected" : ""));
      b.type = "button";
      b.appendChild(el("span", "quiz-option-key", String.fromCharCode(65 + k)));
      b.appendChild(el("span", "quiz-option-text", o.t));
      b.addEventListener("click", function () {
        if (list.classList.contains("is-locked")) return;
        list.classList.add("is-locked");
        answers[i] = k;
        Array.prototype.forEach.call(list.children, function (c) { c.classList.toggle("is-selected", c === b); });
        fill.style.width = Math.round((position(i) / total()) * 100) + "%";
        setTimeout(function () { next(i); }, reduce ? 0 : 320);
      });
      list.appendChild(b);
    });
    s.appendChild(list);
    if (path.length) {
      var back = el("button", "quiz-back", "← " + U.back);
      back.type = "button";
      back.addEventListener("click", function () { renderQuestion(path.pop()); });
      s.appendChild(back);
    }
    show(s, h);
  };

  var next = function (i) {
    path.push(i);
    var o = QS[i].options[answers[i]];
    if (i === 0 && o.skip) {
      for (var k = 1; k < LAST; k++) answers[k] = null;
      return renderQuestion(LAST);
    }
    if (i < LAST) return renderQuestion(i + 1);
    renderResult();
  };

  var ring = function (score) {
    var wrap = el("div", "quiz-score");
    var r = 54, c = 2 * Math.PI * r;
    wrap.innerHTML = '<svg viewBox="0 0 120 120" aria-hidden="true"><circle class="quiz-ring-bg" cx="60" cy="60" r="' + r + '"/><circle class="quiz-ring" cx="60" cy="60" r="' + r + '" stroke-dasharray="' + c.toFixed(1) + '" stroke-dashoffset="' + c.toFixed(1) + '"/></svg>';
    var num = el("p", "quiz-score-num");
    var n = el("span", null, "0");
    num.appendChild(n);
    num.appendChild(el("small", null, "/100"));
    wrap.appendChild(num);
    wrap.setAttribute("role", "img");
    wrap.setAttribute("aria-label", U.scoreLabel + ": " + score + "/100");
    // Fill the ring and count up once it's on screen
    setTimeout(function () {
      wrap.querySelector(".quiz-ring").style.strokeDashoffset = (c * (1 - score / 100)).toFixed(1);
      if (reduce) { n.textContent = score; return; }
      var t0 = performance.now();
      (function tick(t) {
        var k = Math.min(1, (t - t0) / 1200);
        n.textContent = Math.round(score * (1 - Math.pow(1 - k, 3)));
        if (k < 1) requestAnimationFrame(tick);
      })(t0);
    }, 450);
    return wrap;
  };

  var renderResult = function () {
    var R = window.quizEvaluate(D, answers);
    var s = el("div", "quiz-screen quiz-result");
    // "reveal is-in": already shown (the page-entrance styles hide plain kickers)
    s.appendChild(el("p", "kicker quiz-kicker reveal is-in", U.resultKicker));
    var head = el("div", "quiz-result-head");
    var h;
    if (R.noSite) {
      h = el("h2", "quiz-band", U.noSiteTitle);
      head.appendChild(h);
      head.appendChild(el("p", "quiz-band-text", U.noSiteText));
    } else {
      head.appendChild(ring(R.score));
      var bt = el("div", "quiz-band-wrap");
      bt.appendChild(el("p", "quiz-score-label", U.scoreLabel));
      h = el("h2", "quiz-band", R.band.title);
      bt.appendChild(h);
      bt.appendChild(el("p", "quiz-band-text", R.band.text));
      head.appendChild(bt);
    }
    h.tabIndex = -1;
    s.appendChild(head);

    // No weak points at all: the "where it's losing out" block is left out
    if (!R.noSite && R.weakTop.length) {
      var weak = el("div", "quiz-weak");
      weak.appendChild(el("p", "quiz-label", U.weakTitle));
      if (R.weakTop.length) {
        var ul = el("ul", "quiz-weak-list");
        R.weakTop.forEach(function (id) {
          var w = D.weak[id];
          var li = el("li");
          li.appendChild(el("strong", null, w.title));
          li.appendChild(el("span", null, w.line));
          ul.appendChild(li);
        });
        weak.appendChild(ul);
      } else {
        weak.appendChild(el("p", "quiz-weak-none", U.noWeak));
      }
      s.appendChild(weak);
    }

    var P = D.plans[R.plan];
    var plan = el("div", "quiz-plan");
    plan.appendChild(el("p", "quiz-label", U.planTitle));
    plan.appendChild(el("h3", "quiz-plan-name", P.name));
    plan.appendChild(el("p", "quiz-plan-line", R.noSite && P.lineNoSite ? P.lineNoSite : P.line));
    if (P.note) plan.appendChild(el("p", "quiz-plan-note", P.note));
    if (R.alsoEngine && P.also) plan.appendChild(el("p", "quiz-plan-note", P.also));
    var acts = el("div", "quiz-plan-actions");
    var a1 = el("a", "button", P.cta.t);
    a1.href = P.cta.href;
    var a2 = el("a", "quiz-plan-link", P.cta2.t + " →");
    a2.href = P.cta2.href;
    [a1, a2].forEach(function (a) { if (/calendly\.com/.test(a.href)) { a.target = "_blank"; a.rel = "noopener"; } });
    acts.appendChild(a1);
    acts.appendChild(a2);
    plan.appendChild(acts);
    s.appendChild(plan);

    // Full report by email (optional)
    var mail = el("form", "quiz-mail");
    mail.noValidate = true;
    // Nothing to fix: the box offers the result and the guide, not a "report"
    var good = !R.weakAll.length; // site in good shape, or no site yet
    mail.appendChild(el("p", "quiz-mail-title", good ? U.mailTitleGood : R.weakAll.length === 1 ? U.mailTitleOne : U.mailTitle));
    var mt = el("p", "quiz-mail-text");
    var parts = (R.noSite ? U.mailTextNoSite : good ? U.mailTextGood : R.score >= 80 ? U.mailTextMinor : U.mailText).split("{guide}");
    mt.appendChild(document.createTextNode(parts[0]));
    mt.appendChild(el("strong", "quiz-mail-guide", U.mailGuide));
    mt.appendChild(document.createTextNode(parts[1] || ""));
    mail.appendChild(mt);
    var hp = el("input", "hp");
    hp.type = "text"; hp.name = "company"; hp.tabIndex = -1; hp.autocomplete = "off"; hp.setAttribute("aria-hidden", "true");
    mail.appendChild(hp);
    var row = el("div", "quiz-mail-row");
    var inp = el("input", "input");
    inp.type = "email"; inp.name = "Email"; inp.required = true; inp.autocomplete = "email";
    inp.placeholder = U.mailPlaceholder;
    inp.setAttribute("aria-label", U.mailPlaceholder);
    var send = el("button", "button", good ? U.mailSendGood : U.mailSend);
    send.type = "submit";
    row.appendChild(inp);
    row.appendChild(send);
    mail.appendChild(row);
    var msg = el("p", "quiz-mail-msg");
    msg.setAttribute("role", "status");
    mail.appendChild(msg);
    var note = el("p", "quiz-mail-note");
    var noteText = good ? U.mailNoteGood : U.mailNote;
    var cut = noteText.lastIndexOf(". ");
    note.appendChild(document.createTextNode(noteText.slice(0, cut + 2)));
    var pl = el("a", null, noteText.slice(cut + 2));
    pl.href = EN ? "/en/privacy-policy/" : "/politica-de-privacidade/";
    note.appendChild(pl);
    mail.appendChild(note);
    mail.addEventListener("submit", function (e) {
      e.preventDefault();
      var email = inp.value.trim();
      if (!/^\S+@\S+\.\S+$/.test(email)) { inp.focus(); return; }
      send.disabled = true;
      var F = window.siteForms;
      var summary = (R.noSite ? U.noSiteTitle : U.scoreLabel + ": " + R.score + "/100 · " + R.band.title) + "\n" + P.name + "\n\n" +
        QS.map(function (q, i) { return answers[i] == null ? "" : q.q + "\n— " + q.options[answers[i]].t; }).filter(Boolean).join("\n\n");
      var payload = { type: "quiz", email: email, answers: answers, message: summary };
      var w3 = F.formData("Diagnóstico: novo resultado", email);
      w3.append("Email", email);
      w3.append("Mensagem", summary);
      w3.append("Origem", "Diagnóstico do site");
      w3.append("Idioma", EN ? "EN" : "PT");
      F.submit(mail, payload, w3).then(function () {
        row.remove();
        msg.textContent = U.mailOk;
        msg.className = "quiz-mail-msg is-ok";
      }).catch(function () {
        send.disabled = false;
        msg.textContent = U.mailFail;
        msg.className = "quiz-mail-msg is-error";
      });
    });
    s.appendChild(mail);

    var again = el("button", "quiz-back quiz-restart", "↺ " + U.restart);
    again.type = "button";
    again.addEventListener("click", function () { answers = []; path = []; renderQuestion(0); });
    s.appendChild(again);
    show(s, h);
  };

  var start = stage.querySelector(".js-quiz-start");
  if (start) start.addEventListener("click", function () { renderQuestion(0); });
})();
